~()?\"']/g, ' ')\n .replace(/\\s+/g,:
~()?"']/g, ' ')
    .replace(/\s+/g, '')
    .trim();
}

/**
 * Công cụ truy vấn ngữ nghĩa và tìm kiếm có độ chính xác cao
 */
xuất hàm tìm kiếm không đồng bộ(
  truy vấn:chuỗi,
  bộ lọc: SearchFilterOptions = {}
): Promise<{ results: SentenceItem[]; tổng:số; ngữ nghĩaMatches?: SemanticExplanationMatch[] }> {
  const all = đang chờ tảiSentences();
  const normalizedQuery = normalizeText(truy vấn);
  const queryTokens = normalizedQuery? normalizedQuery.split(' ').filter(Boolean) : [];

  const {
    cefr = 'tất cả',
    phần = 'tất cả',
    danh mục = 'tất cả',
    danh mục phụ = 'tất cả',
    ngữ pháp = 'tất cả',
    hình thức = 'tất cả',
    giới hạn = 50,
    bù đắp = 0,
  } = bộ lọc;

  // Lọc qua
  hãy lọc = all.filter(s => {
    if (cefr !== 'all' && s.cefr !== cefr) trả về sai;
    if (section !== 'all' && s.section !==section) trả về sai;
    if (category !== 'all' && s.category !== Category) return false;
    if (danh mục con !== 'tất cả' && s.subcategory !== danh mục con) trả về sai;
    if (grammar !== 'all' && !s.grammar.toLowerCase().includes(grammar.toLowerCase())) trả về sai;
    if (formality !== 'all' && s.formality.toLowerCase() !== formality.toLowerCase()) trả về sai;
    trả về sự thật;
  });

  if (! normalizedQuery) {
    tổng const = đã lọc.length;
    const được phân trang = đã lọc. slice(offset, offset + limit);
    return { kết quả: được phân trang, tổng số };
  }

  // Thuật toán chấm điểm
  giao diệnScoredItem {
    mục: Câu Item;
    điểm:số;
    khía cạnh: SemanticExplanationMatch['matchedAspect'];
  }

  const đã ghi: ScoredItem[] = [];

  for (const s của bộ lọc) {
    cho điểm = 0;
    let matchAspect: SemanticExplanationMatch['matchedAspect'] = 'english';

    const NormEn = normalizeText(s.english);
    const NormEg = normalizeText(s.arabicEg);
    const NormFusha = normalizeText(s.arabicFusha);
    const NormGrammar = normalizeText(s.grammar);
    const NormPurpose = normalizeText(s.Purpose);

    // Khớp chính xác toàn bộ câu
    if (normEn === normalizedQuery) {
      điểm += 100;
      MatchAspect = 'tiếng Anh';
    } else if (normEg === normalizedQuery) {
      điểm += 95;
      matchAspect = 'tiếng Ả Rập-ví dụ';
    } else if (normFusha === normalizedQuery) {
      điểm += 90;
      matchAspect = 'tiếng Ả Rập-fusha';
    }

    //Chuỗi con chứa
    if (normEn.includes(normalizedQuery)) {
      điểm += 50;
      MatchAspect = 'tiếng Anh';
    } else if (normEg.includes(normalizedQuery)) {
      điểm += 45;
      matchAspect = 'tiếng Ả Rập-ví dụ';
    } else if (normFusha.includes(normalizedQuery)) {
      điểm += 40;
      matchAspect = 'tiếng Ả Rập-fusha';
    } else if (normGrammar.includes(normalizedQuery)) {
      điểm += 35;
      matchAspect = 'ngữ pháp';
    } else if (normPurpose.includes(normalizedQuery)) {
      điểm += 30;
      matchAspect = 'khái niệm';
    }

    // Mã thông báo khớp
    hãy để tokenMatches = 0;
    for (mã thông báo const của queryTokens) {
      if (normEn.includes(token)) tokenMatches += 5;
      if (normEg.includes(token)) tokenMatches += 4;
      if (normFusha.includes(token)) tokenMatches += 3;
      if (s.vocabulary.some(v => normalizeText(v).includes(token))) tokenMatches += 4;
      if (s.tags.some(t => normalizeText(t).includes(token))) tokenMatches += 3;
    }
    điểm += tokenMatches;

    nếu (điểm > 0) {
      ghi điểm.push({ item: s, điểm, khía cạnh:matchAspect });
    }
  }

  ghi điểm.sort((a, b) => b.score - a.score);

  // Giải thích ngữ nghĩa khớp với các mục trên cùng
  const ngữ nghĩaMatches: SemanticExplanationMatch[] = ghi.slice(0, 5).map(s => {
    hãy để sắc thái = '';
    if (s.item.grammar.toLowerCase().includes('quá khứ liên tục')) {
      sắc thái = 'Thì quá khứ tiếp diễn cho thấy một sự kiện đang diễn ra tại một thời điểm cụ thể trong quá khứ.';
    } else if (s.item.grammar.toLowerCase().includes('hiện tại hoàn thành liên tục')) {
      sắc thái = 'Thì hiện tại hoàn thành tiếp diễn nhấn mạnh thời gian từ quá khứ và tiếp tục cho đến thời điểm nói.';
    } else if (s.item.grammar.toLowerCase().includes('tương lai hoàn hảo')) {
      sắc thái = 'Thì tương lai hoàn thành diễn tả rằng một sự kiện sẽ được hoàn thành trước một thời điểm cụ thể trong tương lai.';
    } else if (s.item.grammar.toLowerCase().includes('indirect')) {
      sắc thái = 'Hình thức yêu cầu gián tiếp là đỉnh cao của nghi thức ngoại giao trong giao tiếp tiếng Anh.';
    }
    trở về {
      câu: s.item,
      điểm tương tự: Math.min(100, s.score),
      sắc tháiGiải thíchAr: sắc thái,
      matchAspect: s.aspect,
    };
  });

  tổng const = đã ghi điểm. chiều dài;
  const paginated = đã ghi.slice(offset, offset + limit).map(s => s.item);

  trở về {
    kết quả: được phân trang,
    tổng cộng,
    ngữ nghĩa,
  };
}

